package main

import "fmt"

const maxScore = 100

func main() {
	score := 95
	// level 只在这个 else if 块里可见，块外访问会编译报错。
	if score >= 90 {
		fmt.Println("优秀")
	} else if score >= 80 {
		fmt.Println("良好")
	} else {
		fmt.Println("继续练习")
	}
	fmt.Println(score, maxScore)
}

