package main

import "fmt"

func main() {
	sum := 0
	for i := 1; i <= 10; i++ {
		// 只累加偶数，奇数直接进入下一轮。
		if i%2 != 0 {
			continue
		}
		sum += i
	}
	fmt.Println("偶数和:", sum)
}

