func main() {
	scores := []int{60, 72, 85}
	// append 可能扩容并返回新切片，必须接住返回值。
	scores = append(scores, 90)

	total := 0
	for _, score := range scores {
		total += score
	}
	fmt.Println("人数:", len(scores))
