package main

import (
	"fmt"
	"strconv"
)

func main() {
	price, count := 10, 4

	// 两个 int 相除会截断小数，先转成 float64 才是保留小数的除法。
	fmt.Println("单价:", float64(price)/float64(count))

	// 乘法优先于加法；括号既能改变顺序，也能把意图写清楚。
	fmt.Println("总价:", price*count+5)
	fmt.Println("带括号:", price*(count+5))

	// 整数转字符串要用 strconv.Itoa，string(40) 得到的是字符而不是 "40"。
	fmt.Println("字符串拼接:", strconv.Itoa(price*count)+" 元")
}

