package main

import "fmt"

// divmod 用命名返回值一次返回商和余数，末尾的 return 会自动交回它们。
func divmod(a, b int) (quotient, remainder int) {
	quotient = a / b
	remainder = a % b
	return
}

// makeCounter 返回闭包：闭包捕获了 count，多次调用共享同一份状态。
func makeCounter() func() int {
	count := 0
	return func() int {
		count++
		return count
	}
}

func main() {
	// defer 注册的语句在函数返回前执行，适合放收尾动作。
	defer fmt.Println("统计完成")

	quotient, remainder := divmod(17, 5)
	fmt.Println("商与余数:", quotient, remainder)

	next := makeCounter()
	fmt.Println("计数:", next(), next(), next())
}

