package main

import "fmt"

// Counter 记录点击次数，字段小写，只能通过方法读写。
type Counter struct {
	count int
}

// Value 用值接收者读取：不修改对象，拿到副本也没关系。
func (c Counter) Value() int {
	return c.count
}

// Increment 用指针接收者修改：改动会直接落在原对象上。
func (c *Counter) Increment() {
	c.count++
}

func main() {
	counter := Counter{}
	for i := 0; i < 3; i++ {
		counter.Increment() // 等价于 (&counter).Increment()
	}
	fmt.Println("点击数:", counter.Value())
}

