package main

import "fmt"

// checkScore 校验成绩：越界时构造一个说明原因的错误。
func checkScore(score int) (string, error) {
	if score < 0 || score > 100 {
		return "", fmt.Errorf("score=%d 超出 0 到 100", score)
	}
	if score >= 90 {
		return "优秀", nil
	}
	return "合格", nil
}

// saveScore 用 %w 包装下层错误，补上「哪一步失败」的上下文。
func saveScore(score int) error {
	level, err := checkScore(score)
	if err != nil {
		return fmt.Errorf("保存成绩失败: %w", err)
	}
	fmt.Println("保存成功:", score, level)
	return nil
}

func main() {
	for _, score := range []int{99, -3} {
		if err := saveScore(score); err != nil {
			fmt.Println("错误:", err)
		}
	}
}

